import https from 'node:https';

const agent = new https.Agent({ keepAlive: true, maxSockets: 50 });
https.request({ host: 'orders.internal', path: '/orders', agent }, (res) => {
    res.resume(); // drain so the socket returns to the pool
}).end();

public void listOrders(Request req,
        StreamObserver<Order> response) {
    orders.findByCustomer(req.customerId())
        .forEach(response::onNext); // write as the cursor reads
    response.onCompleted(); // closes the stream cleanly
}
